DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "est2-papers-2026-09-26:l1may:q16", "old_status": "needs_source_repair", "status": "ready", "question_id": "28e44bb3-675e-5c92-bec9-b75f5c48b034", "stem": "On the ordinary xy-coordinate plane, in which quadrants do the graphs \\(y=\\sin x\\) and \\(y=\\cos x\\) intersect for \\(0\\le x\\le2\\pi\\)?", "choices": [{"key": "A", "text": "I only"}, {"key": "B", "text": "III only"}, {"key": "C", "text": "I and IV"}, {"key": "D", "text": "II only"}, {"key": "E", "text": "I and II"}], "type": "mcq", "correct": "C", "explanation": "Solving sin x=cos x gives x=π/4 and x=5π/4 in the interval. Their graph points are (π/4,√2/2) and (5π/4,−√2/2). Both x-coordinates are positive; their y-coordinates have opposite signs. The graph intersections therefore lie in quadrants I and IV.", "topic": "Triangles, Trigonometry & Similarity", "note": "Original source image decrypted, hash checked, and visually inspected. Corrected option C from I and III to I and IV; distinguished graph coordinates from unit-circle angle quadrants.", "source_document": "EST II - Math Level 1 - May 2021.pdf", "source_page": 6}, {"id": "est2-papers-2026-09-26:l1may:q26", "old_status": "needs_source_repair", "status": "ready", "question_id": "b13e01d3-b49c-5849-b6b9-86521b23eec8", "stem": "Bag B₁ contains balls labeled 0, 0, 1, 2, 3. Bag B₂ contains balls labeled 2, 3, 4, 0. One ball from B₁ supplies the tens digit and one from B₂ the units digit. How many distinct valid two-digit numbers can be formed?", "choices": [{"key": "A", "text": "25"}, {"key": "B", "text": "12"}, {"key": "C", "text": "20"}, {"key": "D", "text": "16"}, {"key": "E", "text": "144"}], "type": "mcq", "correct": "B", "explanation": "A valid two-digit number must start with 1, 2, or 3: three choices. Each permits four different units digits, 0, 2, 3, or 4. Thus there are 3×4=12 distinct two-digit numbers. Drawing one of the zero-labeled balls first does not produce a two-digit number.", "topic": "Statistics, Probability & Data Analysis", "note": "Original source image decrypted, hash checked, and visually inspected. Clarified that the count is distinct valid numbers, not physical ball-pair draws.", "source_document": "EST II - Math Level 1 - May 2021.pdf", "source_page": 8}, {"id": "est2-papers-2026-09-26:l1oct:q14", "old_status": "needs_source_repair", "status": "ready", "question_id": "7ac32843-d3cb-5162-b4d5-f3fae02bec32", "stem": "For a nonzero real parameter m, how many distinct real roots does \\(x(x^2+1)(mx^2-x-2m)=0\\) have?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "0"}, {"key": "E", "text": "5"}], "type": "mcq", "correct": "C", "explanation": "The first factor gives x=0. The factor x²+1 has no real roots. The quadratic has discriminant 1+8m²>0, so it has two distinct real roots. Their product is −2, so neither is zero. Altogether there are three distinct real roots.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original source image decrypted, hash checked, and visually inspected. Added m≠0 and specified distinct roots; for m=0 the original would have only one distinct real root.", "source_document": "EST II - Math Level 1 - October 2021.pdf", "source_page": 6}, {"id": "est2-papers-2026-09-26:l1oct:q38", "old_status": "needs_source_repair", "status": "ready", "question_id": "845c7e7a-5832-5e39-a9b0-96de90b215af", "stem": "An ellipse has equation \\(x^2/a^2+y^2/b^2=1\\), where a>b>0. Its area is πab=35π and a+b=12. What is its equation?", "choices": [{"key": "A", "text": "\\(x^2/25+y^2/49=1\\)"}, {"key": "B", "text": "\\(x^2/64+y^2/16=1\\)"}, {"key": "C", "text": "\\(x^2/49+y^2/25=1\\)"}, {"key": "D", "text": "\\(x^2/35^2+y^2/12^2=1\\)"}, {"key": "E", "text": "\\(x^2/49-y^2/25=1\\)"}], "type": "mcq", "correct": "C", "explanation": "The numbers a and b have sum 12 and product 35, so they are the roots of t²−12t+35=(t−5)(t−7)=0. Since a>b, a=7 and b=5. Substituting their squares gives x²/49+y²/25=1.", "topic": "Functions, Transformations & Graphs", "note": "Original source image decrypted, hash checked, and visually inspected. Added a>b>0 to make the horizontal major-axis orientation explicit instead of relying on apparent diagram proportions.", "source_document": "EST II - Math Level 1 - October 2021.pdf", "source_page": 14}, {"id": "est2-papers-2026-09-26:l2dec:q37", "old_status": "needs_source_repair", "status": "ready", "question_id": "8bd77556-4760-58d9-b07b-93aeba048af6", "stem": "If m is a positive integer and \\(12m/6!\\) is an integer, what is the smallest possible value of m?", "choices": [{"key": "A", "text": "12"}, {"key": "B", "text": "20"}, {"key": "C", "text": "60"}, {"key": "D", "text": "120"}, {"key": "E", "text": "720"}], "type": "mcq", "correct": "C", "explanation": "Since 6!=720, the fraction is 12m/720=m/60. It is an integer exactly when m is a multiple of 60. The least positive such integer is 60.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original source image decrypted, hash checked, and visually inspected. Added the required positive-integer restriction.", "source_document": "EST II - Math Level 2 - December 2020.pdf", "source_page": 12}, {"id": "est2-papers-2026-09-26:l2june:q02", "old_status": "needs_source_repair", "status": "ready", "question_id": "dc963911-a748-5368-a85d-40227434e37c", "stem": "The vector \\((-1/4,\\,3m+4)\\) is a unit vector. What are the possible values of m, rounded to two decimal places?", "choices": [{"key": "A", "text": "m = −1.01 or −1.66"}, {"key": "B", "text": "m = 1.01 or −1.66"}, {"key": "C", "text": "m = −1.01 or 1.66"}, {"key": "D", "text": "m = 1.01 or 1.66"}, {"key": "E", "text": "m = ±1.01"}], "type": "mcq", "correct": "A", "explanation": "Unit length requires 1/16+(3m+4)²=1. Hence 3m+4=±√15/4 and m=(−16±√15)/12. The roots are approximately −1.010585 and −1.656082, which round to −1.01 and −1.66.", "topic": "Vectors & Coordinate Geometry", "note": "Original source image decrypted, hash checked, and visually inspected. Corrected the printed −1.65 rounding to −1.66, consistently across the distractors, and stated the rounding precision.", "source_document": "EST II - Math Level 2 - June 2021.pdf", "source_page": 2}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='source_review_20260928' AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_20260928','source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
